// Assemble the briefing message. We want a single Slack post with:
//   - Counts of each pending bucket
//   - Deep links so each item is one click away
//   - Skip the post entirely if there's nothing to do (don't train Ian to ignore the channel)

const config = $('Config').first().json;
const prs = $('Get Open PRs').first().json || [];
const topicsResp = $('Get Topics State').first().json || {};
const draftsResp = $('Get Pending Drafts').first().json || {};

// PRs: filter to content engine PRs (title prefix), so manual repo PRs don't pollute the count
const contentPRs = (Array.isArray(prs) ? prs : [])
  .filter(p => p.title && p.title.startsWith('content:'));
const otherPRs = (Array.isArray(prs) ? prs : [])
  .filter(p => p.title && !p.title.startsWith('content:'));

// Notion property text helper
function text(prop) {
  if (!prop) return '';
  const arr = prop.title || prop.rich_text || [];
  return arr.map(t => t.plain_text).join('').trim();
}
function sel(prop) { return prop?.select?.name || ''; }

const topics = topicsResp.results || [];
const suggested = topics.filter(t => sel(t.properties?.Status) === 'Suggested');
const queued = topics.filter(t => sel(t.properties?.Status) === 'Queued');

const drafts = draftsResp.results || [];
const pendingTwitter = drafts.filter(d => sel(d.properties?.Type) === 'Twitter Thread' && sel(d.properties?.Status).includes('Needs Review'));
const pendingVideo = drafts.filter(d => sel(d.properties?.Type) === 'Video Script' && sel(d.properties?.Status).includes('Needs Review'));

const totalPending = contentPRs.length + suggested.length + pendingTwitter.length + pendingVideo.length;

// Skip the post if nothing needs Ian's attention. The whole point is to NOT add noise.
if (totalPending === 0 && otherPRs.length === 0) {
  console.log('Nothing pending — skipping briefing post.');
  return [{ json: { skip: true, reason: 'nothing-pending' } }];
}

// Build sections — only include lines for non-zero counts so the message stays scannable
const sections = [];

if (contentPRs.length > 0) {
  const lines = contentPRs.slice(0, 5).map(p => `   • <${p.html_url}|#${p.number} ${p.title.replace(/^content:\s*/, '')}>`);
  const more = contentPRs.length > 5 ? `\n   • _+${contentPRs.length - 5} more_` : '';
  sections.push(`:newspaper: *${contentPRs.length} post PR${contentPRs.length === 1 ? '' : 's'} awaiting review*\n${lines.join('\n')}${more}`);
}

if (suggested.length > 0) {
  const lines = suggested.slice(0, 5).map(t => `   • ${text(t.properties?.Topic || t.properties?.Name)}`);
  const more = suggested.length > 5 ? `\n   • _+${suggested.length - 5} more_` : '';
  sections.push(`:bulb: *${suggested.length} topic${suggested.length === 1 ? '' : 's'} awaiting approval*\n${lines.join('\n')}${more}\n   _Filter Content Calendar by Status = Suggested_`);
}

if (pendingTwitter.length > 0 || pendingVideo.length > 0) {
  const parts = [];
  if (pendingTwitter.length > 0) parts.push(`${pendingTwitter.length} Twitter thread${pendingTwitter.length === 1 ? '' : 's'}`);
  if (pendingVideo.length > 0) parts.push(`${pendingVideo.length} video script${pendingVideo.length === 1 ? '' : 's'}`);
  sections.push(`:writing_hand: *${parts.join(' + ')} to post*\n   _Open Content Drafts in Notion_`);
}

if (queued.length > 0) {
  sections.push(`:hourglass: *${queued.length} topic${queued.length === 1 ? '' : 's'} queued for the engine* (next run will pick the highest priority)`);
}

if (otherPRs.length > 0) {
  const lines = otherPRs.slice(0, 3).map(p => `   • <${p.html_url}|#${p.number} ${p.title}>`);
  sections.push(`:wrench: *${otherPRs.length} non-content PR${otherPRs.length === 1 ? '' : 's'} open*\n${lines.join('\n')}`);
}

const dateStr = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
const headline = totalPending === 0
  ? `:coffee: *Morning briefing — ${dateStr}*\n\nNo content tasks pending. ${otherPRs.length > 0 ? 'You do have non-content PRs open ↓' : 'You can focus on something else.'}`
  : `:coffee: *Morning briefing — ${dateStr}*\n_${totalPending} item${totalPending === 1 ? '' : 's'} need${totalPending === 1 ? 's' : ''} you today._`;

const message = [headline, ...sections].join('\n\n');

return [{ json: {
  skip: false,
  slackWebhookUrl: config.slackWebhookUrl,
  message,
  totalPending,
}}];
